-- nominees — RLS enabled with zero policies in the source project
-- (locked to service_role/postgres only). Appears unused by the
-- live app (0 rows, superseded by votes.category_id/nominee_id).
create table public.nominees (
    id          uuid primary key default gen_random_uuid(),
    category_id text,
    name        text
);

create table public.system_settings (
    id                       serial primary key,
    event_date               timestamptz not null default '2026-11-26 18:00:00+00',
    updated_at               timestamptz default now(),
    show_live_results        boolean default false,
    lineup_revealed          boolean default false,
    is_registration_open     boolean not null default true,
    is_nomination_open       boolean not null default true,
    is_voting_open           boolean not null default false,
    show_tickets             boolean not null default true,
    show_judges              boolean not null default true,
    show_team                boolean not null default true,
    show_lineup              boolean not null default true,
    is_honorary_voting_open  boolean not null default false,
    show_pre_event           boolean default true,
    show_main_event          boolean default true,
    apply_fan_points         boolean default false,
    winner_id                uuid,
    show_volunteer           boolean not null default true,
    pre_event_date           timestamptz
);

create table public.notifications (
    id         uuid primary key default gen_random_uuid(),
