create or replace function public.is_admin()
returns boolean
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
  return exists (
    select 1
    from public.user_roles
    where user_roles.user_id = auth.uid()
    and user_roles.role = 'admin'
  );
end;
$function$;

create or replace function public.get_my_role()
returns text
language sql
stable security definer
as $function$
  select role from user_roles where user_id = auth.uid() limit 1;
$function$;

create or replace function public.get_user_count()
returns bigint
language sql
stable security definer
set search_path to 'public'
as $function$
    select count(*) from auth.users;
$function$;

create or replace function public.log_activity(p_kind text, p_title text, p_message text, p_tag text, p_image text, p_link text)
returns void
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
    insert into activity_feed(kind, title, message, tag, image_url, link_tab)
    values (p_kind, p_title, p_message, p_tag, p_image, p_link);
end;
$function$;

create or replace function public.confirm_ticket_payment(ticket_id uuid)
returns void
language plpgsql
security definer
as $function$
BEGIN
  UPDATE tickets SET payment_status = 'paid' WHERE id = ticket_id;
END;
$function$;

create or replace function public.confirm_nomination_payment(nom_id uuid)
returns void
language plpgsql
security definer
as $function$
BEGIN
  UPDATE nominations SET payment_confirmed = true WHERE id = nom_id;
END;
$function$;

create or replace function public.enforce_contestant_cap()
returns trigger
language plpgsql
security definer
as $function$
begin
    if (select count(*) from contestants where payment_ref is not null) >= 30 then
        raise exception 'REGISTRATION_FULL';
    end if;
    return new;
end;
$function$;

create or replace function public.force_pending_on_paid_tickets()
returns trigger
language plpgsql
as $function$
begin
    if new.amount > 0 then
        new.payment_status := 'pending';
    end if;
    return new;
end;
$function$;

create or replace function public.cast_fan_vote(p_contestant_id text)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare v_uid uuid := auth.uid();
begin
    if v_uid is null then
        return jsonb_build_object('error', 'not authenticated');
    end if;
    insert into public.votes (user_id, category_id, nominee_id)
    values (v_uid, 'fan_favourite', p_contestant_id)
    on conflict (user_id, category_id)
    do update set nominee_id = excluded.nominee_id, created_at = now();
    return jsonb_build_object('ok', true);
end;
$function$;

create or replace function public.cast_fan_vote(p_contestant_id uuid)
returns void
language plpgsql
security definer
as $function$
BEGIN
  INSERT INTO votes (user_id, category_id, nominee_id)
  VALUES (auth.uid(), 'fan_favourite', p_contestant_id)
  ON CONFLICT (user_id, category_id)
  DO UPDATE SET nominee_id = EXCLUDED.nominee_id;
END;
$function$;

create or replace function public.trg_log_dispatch()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
    perform log_activity('dispatch', new.headline, new.message, coalesce(new.tag,'announcement'), null, 'home');
    return new;
end;
$function$;

create or replace function public.trg_log_contestant_featured()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
    if new.is_featured is true and (old.is_featured is distinct from true) then
        perform log_activity('contestant', new.full_name,
            new.full_name || ' just joined The Lineup' || case when new.department is not null then ' · ' || new.department else '' end,
            null, new.headshot_url, 'lineup');
    end if;
    return new;
end;
$function$;

create or replace function public.trg_log_gallery()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
    perform log_activity('gallery', null,
        case when new.caption is not null then '📸 New in the Gallery: ' || new.caption else '📸 New in the Gallery' end,
        null, new.image_url, 'gallery');
    return new;
end;
$function$;

