create or replace function public.trg_log_ticket_paid()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
    buyer_name text;
    other_count int;
    msg text;
begin
    if new.payment_status = 'paid' and (tg_op = 'INSERT' or old.payment_status is distinct from 'paid') then
        select coalesce(nullif(trim(raw_user_meta_data->>'full_name'), ''), split_part(email, '@', 1))
          into buyer_name
          from auth.users where id = new.user_id;

        select count(*) into other_count from tickets
          where tier_name = new.tier_name and payment_status = 'paid';
        other_count := greatest(other_count - 1, 0);

        msg := coalesce(buyer_name, 'Someone')
             || case when other_count > 0
                    then ' and ' || other_count || case when other_count = 1 then ' other' else ' others' end
                    else ''
                end
             || ' just purchased a ' || new.tier_name || ' ticket 🎟️';

        perform log_activity('ticket', null, msg, null, null, 'tickets');
    end if;
    return new;
end;
$function$;

create or replace function public.trg_log_app_controls()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
begin
    if new.is_registration_open is distinct from old.is_registration_open then
        perform log_activity('control', null, case when new.is_registration_open
            then '📝 Contestant Registration is now OPEN!' else '📝 Contestant Registration is now closed.' end,
            null, null, 'register');
    end if;
    if new.is_nomination_open is distinct from old.is_nomination_open then
        perform log_activity('control', null, case when new.is_nomination_open
            then '✨ Nominations are now OPEN — go nominate!' else '✨ Nominations are now closed.' end,
            null, null, 'nominate');
    end if;
    if new.is_voting_open is distinct from old.is_voting_open then
        perform log_activity('control', null, case when new.is_voting_open
            then '🗳️ Fan Favourite Voting is now OPEN!' else '🗳️ Voting is now closed.' end,
            null, null, 'vote');
    end if;
    if new.show_tickets is distinct from old.show_tickets then
        perform log_activity('control', null, case when new.show_tickets
            then '🎟️ Ticket sales are now OPEN!' else '🎟️ Ticket sales are now closed.' end,
            null, null, 'tickets');
    end if;
    if new.show_lineup is distinct from old.show_lineup then
        perform log_activity('control', null, case when new.show_lineup
            then '👗 The Lineup has been revealed!' else '👗 The Lineup is hidden for now.' end,
            null, null, 'lineup');
    end if;
    if new.show_judges is distinct from old.show_judges then
        perform log_activity('control', null, case when new.show_judges
            then '⚖️ Meet the Judges — now revealed!' else '⚖️ Judges panel is hidden for now.' end,
            null, null, 'judges');
    end if;
    if new.show_team is distinct from old.show_team then
        perform log_activity('control', null, case when new.show_team
            then '👥 Meet the Team — now revealed!' else '👥 Team page is hidden for now.' end,
            null, null, 'team');
    end if;
    if new.show_volunteer is distinct from old.show_volunteer then
        perform log_activity('control', null, case when new.show_volunteer
            then '🙋 Volunteer signups are now OPEN!' else '🙋 Volunteer signups are now closed.' end,
            null, null, 'volunteer');
    end if;
    return new;
end;
$function$;

-- ⚠ REPLACE the URL and anon key below with the NEW project's own
-- values (Settings → API → Project URL / anon public key) once the
-- new project exists. Left as the old project's values would call
-- a send-push function that no longer has any subscribers.
create or replace function public.trg_push_activity_feed()
returns trigger
language plpgsql
security definer
set search_path to 'public', 'extensions'
as $function$
begin
    perform net.http_post(
        url     := 'REPLACE_WITH_NEW_PROJECT_URL/functions/v1/send-push',
        headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer REPLACE_WITH_NEW_PROJECT_ANON_KEY',
            'apikey', 'REPLACE_WITH_NEW_PROJECT_ANON_KEY'
        ),
        body    := jsonb_build_object(
            'title', coalesce(new.title, 'Crème De La Style'),
            'body', new.message,
            'link_tab', new.link_tab,
            'image_url', new.image_url
        )
    );
    return new;
end;
$function$;


-- ─────────────────────────────────────────────────────────
-- TRIGGERS
-- ─────────────────────────────────────────────────────────
create trigger on_activity_feed_push after insert on public.activity_feed
    for each row execute function public.trg_push_activity_feed();

create trigger on_challenge_insert after insert on public.challenges
    for each row execute function public.trg_log_challenge();
create trigger on_challenge_closed after update on public.challenges
    for each row execute function public.trg_log_challenge_closed();

create trigger contestant_cap_trigger before insert on public.contestants
    for each row execute function public.enforce_contestant_cap();
create trigger on_contestant_featured after update on public.contestants
    for each row execute function public.trg_log_contestant_featured();

create trigger on_dispatch_insert after insert on public.dispatches
    for each row execute function public.trg_log_dispatch();

create trigger on_gallery_insert after insert on public.gallery_media
    for each row execute function public.trg_log_gallery();

create trigger on_judge_insert after insert on public.judges
    for each row execute function public.trg_log_judge();

create trigger on_sponsor_insert after insert on public.sponsors
    for each row execute function public.trg_log_sponsor();

create trigger on_app_controls_update after update on public.system_settings
    for each row execute function public.trg_log_app_controls();

create trigger on_team_insert after insert on public.team_members
    for each row execute function public.trg_log_team();

create trigger trg_force_pending_tickets before insert on public.tickets
    for each row execute function public.force_pending_on_paid_tickets();
create trigger on_ticket_paid after insert or update on public.tickets
    for each row execute function public.trg_log_ticket_paid();

create trigger on_poll_insert after insert on public.urgent_polls
    for each row execute function public.trg_log_poll();


